                ],
            ],
            [
                'label' => 'Verse 2',
                'kind' => 'verse',
                'num' => 2,
                'lines' => [
                    'Sometimes mid scenes of deepest gloom, Sometimes where Eden\'s bowers bloom, By waters still, ov\'r troubled sea, Still \'tis His hand that leadeth me.',
